sql.if:
AND (
(
d.tenant_id = #{ioTDevice.tenantId}

  OR ((d.tenant_id is null or d.tenant_id = '') AND d.creator_id IN

    #{scopeUnionId}

  )

)

  OR (
  d.creator_id = #{ioTDevice.params.pendingOwnerUnionId}
  AND (
  p.tenant_id = #{ioTDevice.tenantId}
  OR (
  (p.tenant_id is null or p.tenant_id = '')
  AND (
  p.creator_id = #{ioTDevice.tenantId}
  OR EXISTS (
  SELECT 1 FROM iot_user pu
  WHERE pu.union_id = p.creator_id
  AND pu.tenant_id = #{ioTDevice.tenantId}
  )

    OR p.creator_id IN

      #{scopeUnionId}


  )
  )
  )
  )

)

AND (

  (
  d.creator_id = #{ioTDevice.params.pendingOwnerUnionId}
  AND p.creator_id IN

    #{scopeUnionId}

  )
  OR

(

  d.dept_id IN

    #{scopeDeptId}



  OR


  d.creator_id IN

    #{scopeUnionId}


)
)

AND (
d.tenant_id = #{dev.tenantId}

  OR ((d.tenant_id is null or d.tenant_id = '') AND d.creator_id IN

    #{scopeUnionId}

  )

)

AND (

  d.dept_id IN

    #{scopeDeptId}



  OR


  d.creator_id IN

    #{scopeUnionId}


)

mapper.select:
SELECT p.name AS product_name, d.product_key, p.third_platform, p.device_node, p.store_policy, d.device_name, d.device_id, d.iot_id, d.state, d.device_address, SUBSTRING_INDEX(d.coordinate, ',', 1) AS longitude, SUBSTRING_INDEX(d.coordinate, ',', -1) AS latitude, d.signal_strength, d.device_tag, FROM_UNIXTIME(d.create_time) AS create_time, FROM_UNIXTIME(d.online_time) AS online_time, FROM_UNIXTIME(d.registry_time) AS registry_time, d.detail FROM iot_device d LEFT JOIN iot_product p ON d.product_key = p.product_key
AND d.iot_id LIKE CONCAT('%', #{ioTDevice.iotId}, '%')
AND d.device_id LIKE CONCAT('%', #{ioTDevice.deviceId}, '%')
AND d.product_key LIKE CONCAT('%', #{ioTDevice.productKey}, '%')
AND d.device_name LIKE CONCAT('%', #{ioTDevice.deviceName}, '%')
AND d.`instance` = #{ioTDevice.instance}
AND d.application = #{ioTDevice.application}
AND d.state = #{ioTDevice.state}
AND d.areas_id = #{ioTDevice.areasId}
ORDER BY d.create_time DESC LIMIT 200000

SELECT a.id `id`, up.app_unique_id `applicationId`, up.app_id, u.union_id `userUnionId`, u.id `userId`, a.tenant_id `tenantId`, a.device_id `deviceId`, a.device_name `deviceName`, a.coordinate `coordinate`, a.product_key `productKey`, a.product_name `productName`, dp.creator_id `productCreatorId`, a.ext_device_id `extDeviceId`, a.state `state`, a.iot_id `iotId`, a.registry_time `registryTime`, a.online_time `onlineTime`, a.gw_product_key `gwProductKey`, a.device_secret `deviceSecret`, (CASE when a.derive_metadata is null or a.derive_metadata = '' then dp.metadata else a.derive_metadata end ) `metadata`, ( CASE WHEN up.app_status IS NULL THEN 1 ELSE up.app_status END ) `appDisable`, dp.third_platform thirdPlatform, dp.device_node `deviceNode`, dp.configuration `configuration`, dp.store_policy storePolicy, dp.store_policy_configuration storePolicyCfg, IFNULL(da.id,0) `shadow`, tg.tag_value `devGroupId`, a.configuration devConfiguration, a.areas_id areasId, a.detail detail FROM iot_device a LEFT JOIN iot_product dp ON dp.product_key = a.product_key LEFT JOIN iot_user u ON a.creator_id = u.union_id LEFT JOIN iot_user_application up ON up.app_unique_id = a.application LEFT JOIN iot_device_shadow da on da.iot_id=a.iot_id LEFT JOIN iot_device_tags tg on (tg.iot_id=a.iot_id AND tg.tag_key='devGroup')
AND a.product_key = #{productKey}
AND a.device_id = #{deviceId}
AND a.iot_id = #{iotId}
AND a.ext_device_id = #{extDeviceId}
AND a.gw_product_key = #{gwProductKey}
AND dp.third_platform = #{thirdPlatform}
limit 1

SELECT up.app_unique_id `applicationId`, u.union_id `userUnionId`, u.id `userId`, a.device_id `deviceId`, a.device_name `deviceName`, a.coordinate `coordinate`, a.product_key `productKey`, a.product_name `productName`, a.ext_device_id `extDeviceId`, a.state `state`, a.iot_id `iotId`, a.registry_time `registryTime`, a.online_time `onlineTime`, (CASE when a.derive_metadata is null or a.derive_metadata = '' then dp.metadata else a.derive_metadata end ) `metadata`, ( CASE WHEN up.app_status IS NULL THEN 1 ELSE up.app_status END ) `appDisable`, up.notify_url `notifyUrl`, up.up_topic `upTopic`, up.down_topic `downTopic`, up.scope, dp.third_platform thirdPlatform, dp.device_node `deviceNode`, dp.configuration `configuration`, IFNULL(da.id,0) `shadow`, tg.tag_value `devGroupId` FROM iot_device a LEFT JOIN iot_product dp ON dp.product_key = a.product_key LEFT JOIN iot_user u ON a.creator_id = u.union_id LEFT JOIN iot_user_application up ON up.app_unique_id = a.application LEFT JOIN iot_device_shadow da on da.iot_id=a.iot_id LEFT JOIN iot_device_tags tg on (tg.iot_id=a.iot_id AND tg.tag_key='devGroup')
AND a.device_id = #{deviceId}
AND a.product_key = #{productKey}
AND a.iot_id = #{iotId}
AND a.ext_device_id = #{extDeviceId}
AND a.gw_product_key = #{gwProductKey}

